Paid Social Delivers Higher Conversion R.test_condition:
-- compute conversion rates by source with minimum sample sizes
CR_paid_social = SUM(toInt64OrNull(companies.properties_num_conversion_events)) FILTER (WHERE companies.properties_hs_analytics_source = 'PAID_SOCIAL') / NULLIF(SUM(toInt64OrNull(companies.properties_hs_analytics_num_visits)) FILTER (WHERE companies.properties_hs_analytics_source = 'PAID_SOCIAL'), 0);
CR_others = SUM(toInt64OrNull(companies.properties_num_conversion_events)) FILTER (WHERE companies.properties_hs_analytics_source <> 'PAID_SOCIAL' AND companies.properties_hs_analytics_source IS NOT NULL) / NULLIF(SUM(toInt64OrNull(companies.properties_hs_analytics_num_visits)) FILTER (WHERE companies.properties_hs_analytics_source <> 'PAID_SOCIAL' AND companies.properties_hs_analytics_source IS NOT NULL), 0);
visits_paid_social = SUM(toInt64OrNull(companies.properties_hs_analytics_num_visits)) FILTER (WHERE companies.properties_hs_analytics_source = 'PAID_SOCIAL');
visits_others = SUM(toInt64OrNull(companies.properties_hs_analytics_num_visits)) FILTER (WHERE companies.properties_hs_analytics_source <> 'PAID_SOCIAL' AND companies.properties_hs_analytics_source IS NOT NULL);
visits_paid_social >= 30 AND visits_others >= 30 AND CR_paid_social >= CR_others * 1.30

Revenue Concentrated in Few Industries.test_condition:
-- compute revenue by industry and concentration
rev_by_industry = SUM(toFloat64OrNull(companies.properties_total_revenue)) GROUP BY companies.properties_industry;
(SUM of top 2 rev_by_industry) / (SUM of all rev_by_industry) >= 0.50
